INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-05' FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Voluntary e-invoicing (JP PINT / Peppol) layered on a mandatory paper-or-electronic Qualified Invoice System since 2023 -- no e-invoicing issuance mandate', 'This deep-dive page reflects publicly available Digital Agency and National Tax Agency guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current status directly with the NTA, the Digital Agency, or a Japanese tax adviser before relying on this page for compliance decisions.', 'Japan''s Digital Agency was established in September 2021 and became the country''s Peppol Authority; a month later, registration opened for the Qualified Invoice System, which took effect 1 October 2023. JP PINT, a voluntary Peppol e-invoicing standard, has developed alongside it, while transitional input-tax-credit relief for non-registered suppliers steps down through 2031.', 'There is no mandated invoice file format in Japan -- qualified invoices can be paper, PDF, or any other format, as long as they contain the required content. Businesses that choose to e-invoice electronically can use JP PINT, Japan''s voluntary Peppol PINT BIS Billing-compliant specification maintained by the Digital Agency.', 'No B2B or B2G e-invoicing issuance mandate applies in Japan -- every business remains free to send paper, PDF, or electronic invoices. The Qualified Invoice System instead governs invoice CONTENT and supplier registration for consumption-tax input-credit purposes, applying wherever a business buyer wants to claim that credit, regardless of format or how the invoice is transmitted.', 'Because Japan has no issuance mandate to prepare for, most of the practical work here is about the Qualified Invoice System''s registration and content requirements -- plus deciding, entirely optionally, whether JP PINT/Peppol adoption is worth it for your trading relationships.', 'Japan''s Qualified Invoice System has no direct financial penalty for a business that doesn''t register -- the enforcement mechanism is economic, not punitive: an unregistered supplier''s invoices don''t support full input-tax-credit deduction for their business customers, a market disadvantage rather than a fine.', 'Japan has no e-invoicing issuance mandate -- paper and PDF invoices remain fully valid. What is mandatory, since 1 October 2023, is the Qualified Invoice System: to claim input tax credit, a business buyer generally needs an invoice from an NTA-registered supplier containing specific content, including a 14-digit T-number -- a registration and documentation regime, not a transmission-format rule. Separately, the Digital Agency has promoted JP PINT, a voluntary Peppol-based e-invoicing standard, since 2021. Transitional relief on credits for purchases from unregistered suppliers is already tapering down through 2031.', '🇯🇵' FROM countries WHERE name_en = 'Japan';
