INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '7 years', 'Invoice retention requirement');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Qualified invoice mandatory content', '[["Issuer info", "Issuer''s name and 14-digit T-number (registration number)"], ["Issuance date", "Date the invoice was issued"], ["Itemized description", "Description of goods/services supplied"], ["Tax-differentiated amounts", "Amounts split by the applicable consumption-tax rate (standard/reduced)"], ["Consumption tax total", "Total consumption tax amount for the invoice"]]', 'None of this requires the invoice to be issued electronically -- a paper or PDF invoice containing this content is a fully valid qualified invoice.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'JP PINT / Peppol specification (voluntary)', '[["Standard", "JP PINT -- Japan''s Peppol PINT BIS Billing-compliant e-invoicing specification"], ["Governance", "Developed by the Digital Agency together with EIPA, a Japanese industry body"], ["Current version", "v1.1.3 (as of 8 June 2026), covering the Standard Invoice JP PINT, JP BIS Self-Billing Invoice, and JP BIS Invoice for Non-tax-Registered Businesses"], ["Legal status", "Entirely voluntary -- no law requires adoption"]]', 'JP PINT is a genuinely real, actively maintained specification -- it''s simply not mandatory for any business.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Registration & retention', '[["Registration authority", "National Tax Agency (NTA)"], ["Registration window", "Opened 1 October 2021, ahead of the 1 October 2023 effective date"], ["T-number format", "A 14-digit registration number assigned to each registered qualified invoice issuer"], ["Retention period", "Minimum 7 years for qualified invoices and related records"]]', NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The voluntary JP PINT/Peppol flow', 'For the minority of businesses that choose to e-invoice electronically via JP PINT, an invoice moves through this sequence -- entirely optional at every step:', 'Nothing about this flow is required. Most Japanese businesses still exchange paper or PDF invoices and remain fully compliant with the Qualified Invoice System as long as the invoice content is correct.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Supplier''s system generates a JP PINT-formatted e-invoice');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Sent via the supplier''s Peppol Access Point');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Transmitted across the Peppol four-corner network');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Delivered to the buyer''s Access Point');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Received directly into the buyer''s system as structured data');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s actually mandatory vs. voluntary, by layer', '[["Invoice format/issuance", "Not mandated -- paper, PDF, or electronic all valid"], ["Qualified invoice content & registration", "Mandatory since 1 Oct 2023, for input-tax-credit purposes"], ["JP PINT / Peppol adoption", "Entirely voluntary, government-endorsed standard"], ["General B2B e-invoicing mandate", "Does not exist -- no proposal with a dated timeline found"]]', 'It''s easy to conflate Japan''s real 2023 tax mandate with an e-invoicing mandate -- they''re not the same thing. Only the first is legally required.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The transitional relief taper', '[["1 Oct 2023 - 30 Sep 2026", "80% of tax on purchases from non-registered suppliers deductible"], ["1 Oct 2026 - 30 Sep 2028", "70% deductible"], ["1 Oct 2028 - 30 Sep 2030", "50% deductible"], ["1 Oct 2030 - 30 Sep 2031", "30% deductible"]]', 'The NTA source reviewed didn''t explicitly confirm the post-Sep-2031 end state -- treat full elimination after that date as expected, not officially confirmed here.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💰 No direct fine for skipping registration', NULL, NULL, 'Unlike many jurisdictions in this tracker, Japan''s Qualified Invoice System carries no direct financial penalty for a business that simply chooses not to register as a qualified invoice issuer. Research found no bespoke fine schedule tied to non-registration itself.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📉 The real cost is commercial, not punitive', NULL, NULL, 'An unregistered supplier can still trade freely, but its business customers can''t claim full input tax credit on its invoices -- only a shrinking share during the transitional period (80% falling to 30% by 2030-2031). That makes an unregistered supplier a less attractive counterparty, especially to VAT-sensitive buyers. It''s an economic, market-based enforcement mechanism, closer in spirit to a market incentive than a fine-based compliance regime.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🗓 A taper, not a cliff', NULL, NULL, 'Rather than a single mandate date with a fine attached, Japan''s enforcement lever is the gradual step-down of transitional relief itself: 80% (2023-2026), 70% (2026-2028), 50% (2028-2030), 30% (2030-2031). The pressure to register builds over nearly a decade, not overnight.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Ordinary tax-compliance risk still applies', NULL, NULL, 'While there''s no invoice-specific penalty, Japan''s general consumption tax rules -- inaccurate return penalties, record-keeping requirements -- still apply as normal. Getting qualified-invoice content wrong, or failing to retain records for the required 7 years, can still create downstream tax exposure even though the Qualified Invoice System itself has no dedicated fine schedule.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your registration status with the NTA', 'If your business customers rely on your invoices for input tax credit, confirm you''re registered as a qualified invoice issuer and have your 14-digit T-number ready to display.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Check your invoicing software''s T-number field support', 'Make sure your invoicing template or software can display your T-number alongside the other five mandatory qualified-invoice elements -- issuer name, issuance date, itemized description, tax-differentiated amounts, and the consumption tax total.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Decide whether JP PINT/Peppol adoption makes sense for you', 'Since electronic issuance is entirely optional, weigh whether adopting JP PINT is worth it given your specific trading partners'' plans and systems -- there''s no compliance requirement pushing you toward it.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track the transitional relief taper if you buy from unregistered suppliers', 'Budget for the declining deductible share on purchases from non-registered suppliers -- 70% from October 2026, 50% from October 2028, 30% from October 2030.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for future JP PINT specification updates', 'JP PINT reached v1.1.3 as of 8 June 2026 -- check the Digital Agency''s own JP PINT page periodically if you''ve adopted, or are considering adopting, the standard.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.digital.go.jp/en/policies/electronic_invoice', 0 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Digital Agency — JP PINT (Japan''s Peppol e-invoicing specification)');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.nta.go.jp/', 1 FROM countries WHERE name_en = 'Japan';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'National Tax Agency (NTA) — Qualified Invoice System');
